package io.github.some_example_name;
import io.github.some_example_name.database.*;import io.github.some_example_name.model.*;import java.util.*;
public final class DraftClass2002RegressionTest{public static void main(String[]a){require(DraftClassRepository.hasHistoricalClass(2002),"not registered");List<Player>ps=DraftClassRepository.getClassForYear(2002);require(ps.size()==60,"Expected 60");Set<String>old=new HashSet<>();for(int y=1970;y<=2001;y++)for(Player p:DraftClassRepository.getClassForYear(y))old.add(n(p.getName()));Map<String,Player>m=new HashMap<>();for(Player p:ps){require(p.getAge()==18,"age "+p.getName());require(!old.contains(n(p.getName())),"Repeated "+p.getName());require(m.put(p.getName(),p)==null,"Duplicate "+p.getName());}expect(m,"Andrés Iniesta",Position.CM,66,82,50,76,88,98);expect(m,"Thiago Silva",Position.CB,40,64,78,89,58,97);expect(m,"Sunil Chhetri",Position.ST,69,58,28,84,72,90);System.out.println("Draft class 2002: 60 unique eligible prospects, attributes, positions and balanced potential OK.");}private static String n(String s){return s.toLowerCase(Locale.ROOT);}private static void expect(Map<String,Player>m,String n,Position q,int a,int p,int d,int f,int dr,int originalPot){Player x=m.get(n);require(x!=null&&x.getPrimaryPosition()==q&&x.getPotential()<=originalPot&&x.getTechnicalAttributes().getAtaque()==a&&x.getTechnicalAttributes().getPasse()==p&&x.getTechnicalAttributes().getDefesa()==d&&x.getTechnicalAttributes().getFisico()==f&&x.getTechnicalAttributes().getDrible()==dr,"Bad "+n);}private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}}
